class Solution:
    def calculate(self,s):
        result=0;number=0;sign=1;stack=[]
        for c in s:
            if c.isdigit():number=number*10+int(c)
            elif c in '+-':result+=sign*number;number=0;sign=1 if c=='+' else -1
            elif c=='(':stack.extend([result,sign]);result=0;sign=1
            elif c==')':
                result+=sign*number;number=0
                result=result*stack.pop()+stack.pop()
        return result+sign*number
